// ReceiveBhejnaWebhook operation middleware
func (siw *ServerInterfaceWrapper) ReceiveBhejnaWebhook(w http.ResponseWriter, r *http.Request) {

	ctx := r.Context()

	ctx = context.WithValue(ctx, BhejnaKeyScopes, []string{})

	r = r.WithContext(ctx)

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.ReceiveBhejnaWebhook(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

// ReceiveBhejnaWebhookModeB operation middleware
func (siw *ServerInterfaceWrapper) ReceiveBhejnaWebhookModeB(w http.ResponseWriter, r *http.Request) {

	var err error

	// ------------- Path parameter "location_id" -------------
	var locationId UUIDv7

	err = runtime.BindStyledParameterWithOptions("simple", "location_id", chi.URLParam(r, "location_id"), &locationId, runtime.BindStyledParameterOptions{ParamLocation: runtime.ParamLocationPath, Explode: false, Required: true})
	if err != nil {
		siw.ErrorHandlerFunc(w, r, &InvalidParamFormatError{ParamName: "location_id", Err: err})
		return
	}

	ctx := r.Context()

	ctx = context.WithValue(ctx, BhejnaKeyScopes, []string{})

	r = r.WithContext(ctx)

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.ReceiveBhejnaWebhookModeB(w, r, locationId)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

